<script lang="ts">let result=''; async function load(){result=await (await fetch('http://127.0.0.1:8090/api/framework-sveltekit/catalog')).text()} async function search(event:SubmitEvent){event.preventDefault();const form=event.currentTarget as HTMLFormElement;result=await (await fetch('http://127.0.0.1:8090/api/framework-sveltekit/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({query:new FormData(form).get('query')})})).text()}</script>
<h1>SvelteKit home</h1><p>File-based SSR route with client navigation and a browser-triggered API.</p><a href="/items/item-01">Open item 01</a><button onclick={load}>Load catalog</button><form onsubmit={search}><label>Search <input name="query" value="blue" /></label><button>Search API</button></form><pre data-testid="api-result">{result}</pre>
